mapper.sql:
WITH book AS ( WITH book1 AS ( SELECT '1' seq , ast09_book.* FROM ast09_book WHERE ast09_company_id = #{c.companyId} AND (ast09_ast_class_tree_id, ast09_keep_account_id, ast09_hold_date) IN ( SELECT ast09_ast_class_tree_id, ast09_keep_account_id, MAX(ast09_hold_date) FROM ast09_book WHERE ast09_company_id = #{c.companyId} AND ast09_hold_date <= #{c.holdDate}
AND ast09_keep_account_id = #{c.keepAccountId}
GROUP BY ast09_ast_class_tree_id, ast09_keep_account_id ) UNION ALL SELECT '2' seq , ast11_book_id , ast11_hold_date , ast11_ast_class_tree_id , ast11_keep_account_id , ast11_hold_qty , ast11_pur_amt , ast11_book_amt , ast11_eval_amt , ast11_eval_pl , ast11_first_pur_amt , ast11_first_pur_date , ast11_company_id , ast11_for_pur_amt , ast11_for_book_amt , ast11_for_eval_amt , ast11_for_eval_pl , ast11_fx_pl , ast11_book_end_yn , ast11_acr_int_amt , ast11_for_acr_int_amt , ast11_oci , ast11_for_oci , ast11_lock_up_period_cd , ast11_lock_up_date , ast11_lock_up_qty FROM ast11_book_close WHERE ast11_company_id = #{c.companyId} AND (ast11_ast_class_tree_id, ast11_keep_account_id, ast11_hold_date) IN ( SELECT ast11_ast_class_tree_id, ast11_keep_account_id, MAX(ast11_hold_date) FROM ast11_book_close WHERE ast11_company_id = #{c.companyId} AND ast11_hold_date < #{c.holdDate}
AND ast11_keep_account_id = #{c.keepAccountId}
GROUP BY ast11_ast_class_tree_id, ast11_keep_account_id ) ) SELECT * FROM book1 WHERE (ast09_ast_class_tree_id, ast09_keep_account_id, to_char(ast09_hold_date,'yyyymmdd')||seq) IN ( SELECT ast09_ast_class_tree_id, ast09_keep_account_id, MAX(to_char(ast09_hold_date,'yyyymmdd')||seq) FROM book1 GROUP BY ast09_ast_class_tree_id, ast09_keep_account_id ) )

mapper.select:
SELECT COALESCE(ast06_tr_id, f_create_seq()) AS tr_id , COALESCE(ast06_ast_class_tree_id, ast09_ast_class_tree_id) AS ast_class_tree_id , COALESCE(ast06_deposit_id , ast09_ast_class_tree_id) AS deposit_id , COALESCE(ast06_date , #{c.holdDate}) AS date , COALESCE(ast06_tr_cd, '3700') AS tr_code , COALESCE(ast06_company_id, ast09_company_id) AS company_id , COALESCE(ast06_cur_cd, ast01_cur_cd) AS cur_code , COALESCE(ast06_fx_rate, ast24_apply_fx_rate) AS fx_rate , ast09_for_book_amt AS for_amt , ast09_book_amt AS deposit_book_amt , sys15_corp_id AS corp_id , act02_journal_id AS journal_id , f_ast_class_tree_nm(ast09_ast_class_tree_id) AS class_tree_name , sys15_corp_nm||'('||f_ast_class_tree_nm(ast09_keep_account_id)||')' AS corp_account_name , CASE WHEN ast06_tr_id IS NOT NULL THEN '평가' ELSE '' END AS eval_yn_name , tr.ast06_amt AS amt , tr.ast06_note AS note , tr.ast06_person_id AS person_id , f_emp_kor_nm(ast06_person_id) AS person_name FROM book INNER JOIN ast01_class_tree ON ast01_class_tree_id = ast09_ast_class_tree_id INNER JOIN sys15_corp ON sys15_corp_id = ast01_corp_id LEFT OUTER JOIN ( SELECT * FROM ast06_tr LEFT OUTER JOIN act02_journal ON act02_tr_id = ast06_tr_id WHERE ast06_company_id = #{c.companyId} AND ast06_date = #{c.holdDate} AND ast06_tr_cd = '3700' /* (3700:외화예금 환산평가) */ ) tr ON ( ast06_company_id = ast09_company_id AND ast06_ast_class_tree_id = ast09_ast_class_tree_id AND ast06_date = #{c.holdDate} ) LEFT OUTER JOIN ast24_fx_rate ON ( ast24_company_id = ast09_company_id AND ast24_fx_rate_type = '01' AND /* (01:평가환율) */ ast24_cur_cd = ast01_cur_cd AND ast24_std_date = #{c.holdDate} ) WHERE COALESCE(ast01_asset_type,'1') like #{c.assetType} AND ast01_item_l_class_cd = '10' /* 10:현금 및 예치금 */ AND COALESCE(ast01_cur_cd,'KRW') != 'KRW'
AND sys15_corp_id = #{c.corpId}
ORDER BY sys15_corp_nm collate "ko_KR.utf8", ast01_seq

SELECT count(*)
  FROM ast06_tr
 WHERE ast06_company_id         = #{companyId}
   AND ast06_ast_class_tree_id  = #{astId}
   AND ast06_tr_cd              = '3700'
   AND ast06_date > #{stdDate}

SELECT count(*)
  FROM ast09_book
 WHERE ast09_company_id         = #{companyId}
   AND ast09_ast_class_tree_id  = #{astClassTreeId}
   AND ast09_keep_account_id    = #{keepAccountId}
   AND ast09_hold_date          = #{holdDate}

mapper.update:
UPDATE ast09_book
   SET ast09_eval_amt           = ast09_book_amt + #{fxPl}
     , ast09_fx_pl              = #{fxPl}
 WHERE ast09_company_id         = #{companyId}
   AND ast09_hold_date          = #{holdDate}
   AND ast09_ast_class_tree_id  = #{astClassTreeId}

