 WHERE ast24_company_id     = #{companyId}
   AND ast24_std_date       = #{stdDate}
   AND ast24_fx_rate_type   = #{fxRateType}
   AND ast24_cur_cd         LIKE #{curCode}

SELECT 
  FROM ast24_fx_rate
 WHERE ast24_fx_rate_id = #{fxRateId}
   AND ast24_company_id = #{companyId}

