UPDATE ast24_fx_rate
   SET ast24_std_date      = #{r.stdDate},
       ast24_cur_cd        = #{r.curCode},
       ast24_apply_fx_rate = #{r.applyFxRate},
       ast24_note          = #{r.note}
 WHERE ast24_fx_rate_id    = #{r.fxRateId}
   AND ast24_company_id    = #{companyId}

